// GetPushSessionsRemote returns the configured remote for pushing session logs.
// Returns empty string if not configured (caller should use the default push remote).
// Configuration: strategy_options.push_sessions_remote in .entire/settings.json
func (s *EntireSettings) GetPushSessionsRemote() string {
	if s.StrategyOptions == nil {
		return ""
	}
	val, exists := s.StrategyOptions["push_sessions_remote"]
	if !exists {
		return ""
	}
	if strVal, ok := val.(string); ok && strVal != "" {
		return strVal
	}
	return ""
}

